//! Kernel ABIs match linux/btrfs.h and linux/loop.h; no mount/device mutation.
use super::*;
#[path = "partitioned.rs"]
mod partitioned;
use std::path::PathBuf;
use nix::libc;
use std::{
    ffi::CString,
